        /// Query an AABB for overlapping proxies. The callback class is called for each proxy that overlaps the supplied AABB.
        /// RETURN: performance data
        [LibraryImport(Dll, EntryPoint = "b2DynamicTree_Query")]
        internal static unsafe partial B2TreeStats DynamicTreeQuery(
            in B2DynamicTree tree,
            B2Aabb aabb,
            ulong maskBits,
            B2TreeQueryCallbackFcn callback,
            nint context
        );

        /// Ray cast against the proxies in the tree. This relies on the callback
        /// to perform a exact ray cast in the case were the proxy contains a shape.
        /// The callback also performs the any collision filtering. This has performance
        /// roughly equal to k * log(n), where k is the number of collisions and n is the
        /// number of proxies in the tree.
        /// Bit-wise filtering using mask bits can greatly improve performance in some scenarios.
        /// However, this filtering may be approximate, so the user should still apply filtering to results.
        /// <param name="tree">the dynamic tree to ray cast </param>
        /// <param name="input">the ray cast input data. The ray extends from p1 to p1 + maxFraction * (p2 - p1) </param>
        /// <param name="maskBits">mask bit hint: `bool accept = (maskBits  &amp; node-&gt;categoryBits) != 0;` </param>
        /// <param name="callback">a callback class that is called for each proxy that is hit by the ray </param>
        /// <param name="context">user context that is passed to the callback </param>
        /// RETURN: performance data
        [LibraryImport(Dll, EntryPoint = "b2DynamicTree_RayCast")]
        internal static unsafe partial B2TreeStats DynamicTreeRayCast(
            in B2DynamicTree tree,
            in B2RayCastInput input,
            ulong maskBits,
            B2TreeRayCastCallbackFcn callback,
            nint context
        );

        /// Ray cast against the proxies in the tree. This relies on the callback
        /// to perform a exact ray cast in the case were the proxy contains a shape.
        /// The callback also performs the any collision filtering. This has performance
        /// roughly equal to k * log(n), where k is the number of collisions and n is the
        /// number of proxies in the tree.
        /// <param name="tree">the dynamic tree to ray cast </param>
        /// <param name="input">the ray cast input data. The ray extends from p1 to p1 + maxFraction * (p2 - p1). </param>
        /// <param name="maskBits">filter bits: `bool accept = (maskBits  &amp; node-&gt;categoryBits) != 0;` </param>
        /// <param name="callback">a callback class that is called for each proxy that is hit by the shape </param>
        /// <param name="context">user context that is passed to the callback </param>
        /// RETURN: performance data
        [LibraryImport(Dll, EntryPoint = "b2DynamicTree_ShapeCast")]
        internal static unsafe partial B2TreeStats DynamicTreeShapeCast(
            in B2DynamicTree tree,
            in B2ShapeCastInput input,
            ulong maskBits,
            B2TreeShapeCastCallbackFcn callback,
            nint context
        );

